  --color-success-fg: #5DD6A8;       /* Running */
  --color-warning-bg: #33260A;
  --color-warning-fg: #F0B34A;       /* Stopping/Pending */
  --color-error-bg:   #381519;
  --color-error-fg:   #FF7A66;       /* Failed */
  --color-info-bg:    #11243B;
  --color-info-fg:    #4DA3F5;       /* Info */

  /* Surface */
  --bg-base:     #0F1419;
  --bg-subtle:   #161E2D;
  --bg-elevated: #1F2937;
  --bg-header:   #161E2D;
  --bg-sidebar:  #0B0E13;
  --bg-overlay:  rgba(5,8,13,0.65);

  /* Text */
  --text-primary:    #FAFAFA;
  --text-secondary:  #C8D2DC;
  --text-tertiary:   #9CA3AF;
  --text-link:       #4DA3F5;
  --text-link-hover: #8FC4FA;
  --text-on-primary: #161E2D;
  --text-on-dark:    #FFFFFF;
  --text-disabled:   #6B7785;

  /* Border */
  --border-default: #2C3340;
  --border-subtle:  #232A33;
  --border-strong:  #3A4150;
  --border-focus:   #4DA3F5;
}

[data-theme="light"] {
  /* Primary - AWS Orange (Squid Ink + Anchor Orange) */
  --color-primary-50:  #FFF4E0;
  --color-primary-100: #FFE2A8;
  --color-primary-200: #FFCD66;
  --color-primary-300: #FFB429;
  --color-primary-400: #FFA61C;
